    page) if (( COMP_CWORD == 2 )); then COMPREPLY=( $(compgen -W "search list show save update supersede forget restore confirm retire rename merge move link promote evolve" -- "$cur") ); return; fi; verb="page ${COMP_WORDS[2]}" ;;
